import unittest
from events import unique_event_ids


class EventTests(unittest.TestCase):
    def test_keeps_first_seen_order(self):
        events = [{'id': 'z'}, {'id': 'a'}, {'id': 'z'}, {'id': 'b'}]
        self.assertEqual(unique_event_ids(events), ['z', 'a', 'b'])

    def test_empty(self):
        self.assertEqual(unique_event_ids([]), [])

